+        grpc_ctx.path = http_conv->request_uri;
+        grpc_ctx.content_type = pinfo->match_string; /* only for grpc-web(-text) over http1.1 */
+    }
+    else {
+        /* unexpected protocol error */
+        DISSECTOR_ASSERT_NOT_REACHED();
+    }

